(()=>{function sync(){const top=document.querySelector('.top');document.documentElement.style.setProperty('--app-header-height',(Math.max(0,top?.getBoundingClientRect().bottom||74))+'px')}window.addEventListener('DOMContentLoaded',()=>{sync();const top=document.querySelector('.top');if(top)new ResizeObserver(sync).observe(top)});window.addEventListener('resize',sync);window.addEventListener('scroll',sync,{passive:true,capture:true})})();
(()=>{const pinned=new Map();function pin(el,target,kind='add'){if(!el||!target||pinned.has(el))return;const marker=document.createComment('header-control-origin');if(el.tagName==='BUTTON'&&el.type==='submit'&&el.form){const form=el.form;if(!form.id)form.id='header-form-'+Math.random().toString(36).slice(2);el.setAttribute('form',form.id)}el.before(marker);pinned.set(el,marker);if(target.classList.contains('shortcut-actions')){const label=el.getAttribute('aria-label')||el.title||el.textContent.trim();el.title=label;el.setAttribute('aria-label',label);el.classList.remove('btn','tree-add-solid','location-add');el.style.setProperty('border-radius','50%','important');el.classList.add('shortcut-circle',kind==='history'?'header-history-circle':'header-add-circle');el.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+(kind==='history'?'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>':'<path d="M12 5v14M5 12h14"/>')+'</svg>'}target.append(el)}function arrange(){for(const [el,marker]of pinned){if(!marker.isConnected){el.remove();pinned.delete(el)}}document.querySelectorAll('.view.show>.panel').forEach(panel=>{const head=panel.querySelector(':scope>.head'),content=panel.querySelector(':scope>.content');if(!head||!content)return;let dock=head.querySelector(':scope>.fixed-header-tools');if(!dock){dock=document.createElement('div');dock.className='fixed-header-tools';head.append(dock)}const actions=head.querySelector('.shortcut-actions');if(actions){pin(content.querySelector('#jobs-add'),actions);pin([...content.querySelectorAll('.ti-group-form>button')].find(b=>/^(?:\+\s*)?(?:Adicionar (?:grupo|tipo)|Novo grupo)$/i.test(b.textContent.trim())),actions);pin(content.querySelector('.location-toolbar .location-add'),actions);pin([...content.querySelectorAll('button')].find(b=>/^Histórico de transferências$/i.test(b.textContent.trim())),actions,'history')}for(const selector of ['.jobs-toolbar','.financial-list-controls','.location-toolbar']){for(const el of content.querySelectorAll(selector))pin(el,dock)}dock.hidden=!dock.querySelector('input:not([hidden]),select,button')})}window.addEventListener('DOMContentLoaded',()=>{let pending=false;new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{pending=false;arrange()})}).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});arrange()})})();
(()=>{window.addEventListener('DOMContentLoaded',()=>{let queued=false;const searches=new Map();function refresh(){for(const [input,entry] of searches){if(!input.isConnected){entry.button.remove();searches.delete(input)}}document.querySelectorAll('.view.show>.panel>.head').forEach(head=>{const actions=head.querySelector('.shortcut-actions');if(!actions)return;head.querySelectorAll('.fixed-header-tools input[type="search"]').forEach(input=>{if(searches.has(input))return;const button=document.createElement('button');button.type='button';button.className='shortcut-circle header-search-circle';button.title='Buscar';button.setAttribute('aria-label','Abrir busca');button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>';let open=!!input.value;function toggle(next){open=next;input.hidden=!open;input.classList.toggle('header-search-open',open);button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Recolher busca':'Abrir busca');button.title=open?'Recolher busca':'Buscar';button.classList.toggle('search-has-query',!!input.value);if(open)input.focus()}button.onclick=()=>toggle(!open);input.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();toggle(false);button.focus()}});input.addEventListener('input',()=>button.classList.toggle('search-has-query',!!input.value));searches.set(input,{button});actions.append(button);toggle(open)})})}new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;refresh()})}).observe(document.body,{childList:true,subtree:true});refresh()})})();
